    g = c.Graph(name)
    for key in ('Sources', 'Mapping', 'Approaches'):
        g.socket(key, 'NodeSocketGeometry')
    g.socket('Index', 'NodeSocketInt')
    for key in ('Geometry', 'Transitions'):
        g.socket(key, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); at = c.V(g, inp.outputs['Index'])
    src, mapping, rows = [inp.outputs[k] for k in ('Sources', 'Mapping', 'Approaches')]
    start = c._read(g, rows, 'st_cj_full_start', at, 'INT'); count = c._read(g, rows, 'st_cj_full_count', at, 'INT')
    i = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    vertex = c._read(g, mapping, 'st_cj_vertex', start+i, 'INT')
    edge = c._read(g, mapping, 'st_cj_edge', start+i, 'INT')
    following = c._read(g, mapping, 'st_cj_vertex', start+g.math('MINIMUM', i+1., count-1.), 'INT')
    raw = g.setpos(c._line(g, c.bounded(g, count, 2., c.MAX_CONTROLS)), c._sample(g, src, g.position(), vertex, 'FLOAT_VECTOR'))
    edges = g.node('GeometryNodeInputMeshEdgeVertices')
    a, b = [boundary._edge_sample(g, src, edges.outputs[key], edge, 'INT') for key in ('Vertex Index 1', 'Vertex Index 2')]
    matches = g.math('COMPARE', g.math('MINIMUM', a, b), g.math('MINIMUM', vertex, following))*g.math('COMPARE', g.math('MAXIMUM', a, b), g.math('MAXIMUM', vertex, following))
    matches = c.choose(g, g.math('GREATER_THAN', i, count-1.5), 1., matches)
    sid = c._read(g, rows, 'st_cj_street_id', at, 'INT')
    matches = matches*g.math('COMPARE', boundary._edge_sample(g, src, c.named(g, 'st_street_id', 'INT'), edge, 'INT'), sid)
    matches = matches*g.math('GREATER_THAN', vertex, -.5)*g.math('LESS_THAN', vertex, c._count(g, src)-.5)
    valid = c._stat(g, raw, matches)*g.math('GREATER_THAN', count, 1.5)*g.math('LESS_THAN', count, c.MAX_CONTROLS+.5)
    valid = valid*g.math('GREATER_THAN', start, -.5)*g.math('LESS_THAN', start+count, c._count(g, mapping)+.5)
    for key, kind in (('st_width', 'FLOAT'), ('st_offset', 'FLOAT'), ('st_section_id', 'INT')):
        raw = g.store(raw, key, boundary._edge_sample(g, src, c.named(g, key, kind), edge, kind), 'EDGE', kind)
    local_rows = c._line(g, c.bounded(g, count, 2., c.MAX_CONTROLS))
    for key in ('id', 'vertex', 'before_section', 'after_section', 'minimum_half', 'maximum_slope'):
        kind = 'FLOAT' if key in ('minimum_half', 'maximum_slope') else 'INT'
        local_rows = c._store(g, local_rows, 'st_cd_'+key, c._read(g, mapping, 'st_cd_'+key, start+i, kind), kind)
    declarations = c._select(g, local_rows, g.math('GREATER_THAN', c.named(g, 'st_cd_id', 'INT'), -.5))
    out = g.node('NodeGroupOutput')
    for key, value in (('Geometry', raw), ('Transitions', declarations), ('Valid', valid)):
        g.bind(value, out.inputs[key])
    return g.g


